def int_to_mini_roman(count_bucket):
    # Mapping of decimal values to Roman numeral characters in lower case
    numeral_map = {
        1000: 'm',  900: 'cm',  500: 'd',  400: 'cd',
        100:  'c',  90:  'xc',  50:  'l',  40:  'xl',
        10:   'x',  9:   'ix',  5:   'v',  4:   'iv',  1:   'i'
    }

    result = []

    # Subtracting largest possible values first from the number and appending Roman numeral characters accordingly
    for value in numeral_map:
        while count_bucket >= value:
            result.append(numeral_map[value])
            count_bucket -= value

    # Joining all Roman numeral characters into one string and converting it to lower case
    return ''.join(result).lower()

