def lps(key_first):
    n = len(key_first)

    # Initialize the dp array where dp[i][j] will be storing the length of the longest palindromic subsequence in string[i:j+1]
    dp = [[0 for j in range(n)] for i in range(n)]

    # Fill the dp array in bottom-up manner
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            if length == 1:
                dp[i][j] = 1  # Single character string is palindromic of length 1

            elif key_first[i] == key_first[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2  # Two characters match and the rest forms a palindromic sequence

            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])  # No match found

    return dp[0][-1]

